// Editor document and Rust document mapping, and the element-level diff the editor sends to the
// core (`screenplay.apply_edits`). Ported from the Windows editor's `model.ts`. Pure functions.
//
// The core is the source of truth: the editor keeps a baseline snapshot of what the core has, and
// sends the ops that turn the baseline into the current editor state. Ops are generated by
// simulating their effect so every index refers to the state after the previous op, the same
// semantics the core applies.
//
// The editor itself is a text view, so it produces a flat list of `EditorBlock` values (the
// counterpart of the Windows editor's ProseMirror blocks). Every scene heading block starts a new
// scene and the blocks after it are that scene's elements.

import Foundation
import OpenFrameCore

public struct ScreenplayElementSnap: Hashable, Sendable {
    public var id: String
    public var type: ElementType
    public var text: String
    /// The custom element definition of a `custom` element.
    public var customElementId: String?

    public init(id: String, type: ElementType, text: String, customElementId: String? = nil) {
        self.id = id
        self.type = type
        self.text = text
        self.customElementId = customElementId
    }
}

public struct ScreenplaySceneSnap: Hashable, Sendable {
    public var id: String
    public var heading: String
    public var elements: [ScreenplayElementSnap]

    public init(id: String, heading: String, elements: [ScreenplayElementSnap] = []) {
        self.id = id
        self.heading = heading
        self.elements = elements
    }
}

public typealias ScreenplaySnapshot = [ScreenplaySceneSnap]

/// One block of the editor: a scene heading or an element. `id` is nil for a block the editor has
/// just created; `assignIds` gives it one before any sync happens.
public struct EditorBlock: Hashable, Sendable {
    public var id: String?
    public var kind: ElementType
    public var text: String
    /// The definition of a `custom` block.
    public var customElementId: String?

    public init(id: String? = nil, kind: ElementType, text: String = "", customElementId: String? = nil) {
        self.id = id
        self.kind = kind
        self.text = text
        self.customElementId = customElementId
    }
}

public enum ScreenplayModelError: Error, Equatable {
    case elementNotFound(String)
    case sceneNotFound(String)
    case missingId
    case unsupportedOp(String)
}

public enum ScreenplayModel {
    public static func snapshot(fromScenes scenes: [ScreenplaySceneDto]) -> ScreenplaySnapshot {
        scenes.map { s in
            ScreenplaySceneSnap(
                id: s.id,
                heading: s.heading,
                elements: s.elements.map {
                    ScreenplayElementSnap(id: $0.id, type: $0.elementType, text: $0.text, customElementId: $0.customElementId)
                })
        }
    }

    /// The editor blocks of a snapshot. A scene heading element inside a scene is shown as an
    /// action, a page break holds no text, and elements that do not allow line breaks lose them.
    /// An empty snapshot becomes a single empty heading, so the document is always valid.
    public static func blocks(from snapshot: ScreenplaySnapshot, rules: ElementRules) -> [EditorBlock] {
        var blocks: [EditorBlock] = []
        for scene in snapshot {
            blocks.append(EditorBlock(id: scene.id, kind: .sceneHeading, text: flatten(scene.heading, as: .sceneHeading, rules: rules)))
            for el in scene.elements {
                let kind: ElementType = el.type == .sceneHeading ? .action : el.type
                switch kind {
                case .pageBreak:
                    blocks.append(EditorBlock(id: el.id, kind: .pageBreak))
                case .custom:
                    blocks.append(EditorBlock(id: el.id, kind: .custom, text: flatten(el.text, as: kind, rules: rules), customElementId: el.customElementId))
                default:
                    blocks.append(EditorBlock(id: el.id, kind: kind, text: flatten(el.text, as: kind, rules: rules)))
                }
            }
        }
        if blocks.isEmpty { blocks.append(EditorBlock(id: nil, kind: .sceneHeading)) }
        return blocks
    }

    private static func flatten(_ text: String, as kind: ElementType, rules: ElementRules) -> String {
        rules.isMultiline(kind) ? text : text.replacingOccurrences(of: "\n", with: " ")
    }

    /// Gives every block without an id, and every block that repeats an earlier id (a split copies
    /// the id), a new one. The first block keeps its id: it stays with its text.
    public static func assignIds(_ blocks: inout [EditorBlock], newId: () -> String = { UUID().uuidString.lowercased() }) {
        var seen = Set<String>()
        for i in blocks.indices {
            if let id = blocks[i].id, !id.isEmpty, !seen.contains(id) {
                seen.insert(id)
            } else {
                let fresh = newId()
                blocks[i].id = fresh
                seen.insert(fresh)
            }
        }
    }

    /// Reads the editor blocks as scenes. Blocks without ids are skipped (ids are assigned before
    /// any sync happens), and body blocks before the first heading are skipped.
    public static func snapshot(fromBlocks blocks: [EditorBlock]) -> ScreenplaySnapshot {
        var out: ScreenplaySnapshot = []
        for b in blocks {
            guard let id = b.id, !id.isEmpty else { continue }
            if b.kind == .sceneHeading {
                out.append(ScreenplaySceneSnap(id: id, heading: b.text))
            } else if !out.isEmpty {
                out[out.count - 1].elements.append(
                    ScreenplayElementSnap(
                        id: id, type: b.kind,
                        text: b.kind == .pageBreak ? "" : b.text,
                        customElementId: b.kind == .custom ? b.customElementId : nil))
            }
        }
        return out
    }

    public static func equal(_ a: ScreenplaySnapshot, _ b: ScreenplaySnapshot) -> Bool {
        // The custom element id of a snapshot compares as nil when absent, so the synthesized
        // equality is exactly the Windows comparison.
        a == b
    }
}

// MARK: - Diff

private final class SimScene {
    let id: String
    var els: [String]
    init(id: String, els: [String]) {
        self.id = id
        self.els = els
    }
}

private extension Array {
    mutating func place(_ item: Element, at index: Int) {
        insert(item, at: Swift.min(Swift.max(index, 0), count))
    }
}

extension ScreenplayModel {
    /// Ops that transform `base` into `next` (see the file comment).
    public static func diff(_ base: ScreenplaySnapshot, _ next: ScreenplaySnapshot) -> [ScreenplayEditOp] {
        var ops: [ScreenplayEditOp] = []
        var baseEl: [String: ScreenplayElementSnap] = [:]
        var baseHeading: [String: String] = [:]
        var loc: [String: String] = [:]
        var sim: [SimScene] = base.map { s in
            baseHeading[s.id] = s.heading
            for e in s.elements {
                baseEl[e.id] = e
                loc[e.id] = s.id
            }
            return SimScene(id: s.id, els: s.elements.map(\.id))
        }
        let nextScenes = Set(next.map(\.id))
        var nextEls = Set<String>()
        for s in next { for e in s.elements { nextEls.insert(e.id) } }

        // 1. Elements that vanished from surviving scenes are deleted. Elements of a scene that
        //    disappears entirely stay with it (recoverable scene delete).
        for s in sim where nextScenes.contains(s.id) {
            s.els = s.els.filter { id in
                if nextEls.contains(id) { return true }
                ops.append(.deleteElement(id: id))
                loc[id] = nil
                return false
            }
        }

        // 2. Scenes: insert new ones and move existing ones into order.
        for (i, ns) in next.enumerated() {
            if let at = sim.firstIndex(where: { $0.id == ns.id }) {
                if at != i {
                    ops.append(.moveScene(id: ns.id, index: Double(i)))
                    let moved = sim.remove(at: at)
                    sim.place(moved, at: i)
                }
            } else {
                ops.append(.insertScene(id: ns.id, index: Double(i), heading: ns.heading))
                sim.place(SimScene(id: ns.id, els: []), at: i)
            }
        }

        // 3. Elements: insert, move, update.
        var simById: [String: SimScene] = [:]
        for s in sim { simById[s.id] = s }
        for ns in next {
            let target = simById[ns.id]!
            for (j, ne) in ns.elements.enumerated() {
                guard let from = loc[ne.id] else {
                    let custom = (ne.type == .custom) ? ne.customElementId.flatMap { $0.isEmpty ? nil : $0 } : nil
                    ops.append(.insertElement(id: ne.id, sceneId: ns.id, index: Double(j), elementType: ne.type, text: ne.text, customElementId: custom))
                    target.els.place(ne.id, at: j)
                    loc[ne.id] = ns.id
                    continue
                }
                let src = simById[from]!
                let cur = src.els.firstIndex(of: ne.id)!
                if from != ns.id || cur != j {
                    ops.append(.moveElement(id: ne.id, sceneId: ns.id, index: Double(j)))
                    src.els.remove(at: cur)
                    target.els.place(ne.id, at: j)
                    loc[ne.id] = ns.id
                }
                let b = baseEl[ne.id]!
                let customChanged = b.customElementId != ne.customElementId
                if b.type != ne.type || b.text != ne.text || customChanged {
                    var elementType: ElementType? = b.type != ne.type ? ne.type : nil
                    let text: String? = b.text != ne.text ? ne.text : nil
                    var customId: String?
                    if customChanged, ne.type == .custom, let c = ne.customElementId, !c.isEmpty {
                        elementType = .custom
                        customId = c
                    }
                    ops.append(.updateElement(id: ne.id, elementType: elementType, text: text, customElementId: customId))
                }
            }
        }

        // 4. Scenes that disappeared (recoverable delete, keeping leftover elements).
        for s in sim where !nextScenes.contains(s.id) {
            ops.append(.deleteScene(id: s.id))
        }

        // 5. Heading text.
        for ns in next {
            if let old = baseHeading[ns.id], old != ns.heading {
                ops.append(.updateScene(id: ns.id, heading: ns.heading))
            }
        }
        return ops
    }

    /// Applies ops to a snapshot with the core's semantics (used to verify the diff in tests).
    public static func apply(_ ops: [ScreenplayEditOp], to base: ScreenplaySnapshot) throws -> ScreenplaySnapshot {
        var scenes = base
        var deleted = Set<String>()
        func live() -> [ScreenplaySceneSnap] { scenes.filter { !deleted.contains($0.id) } }
        func findEl(_ id: String) throws -> (Int, Int) {
            for (si, s) in scenes.enumerated() {
                if let i = s.elements.firstIndex(where: { $0.id == id }) { return (si, i) }
            }
            throw ScreenplayModelError.elementNotFound(id)
        }
        func sceneIndex(_ id: String) throws -> Int {
            guard let i = scenes.firstIndex(where: { $0.id == id }) else { throw ScreenplayModelError.sceneNotFound(id) }
            return i
        }
        func position(_ index: Double?, in count: Int) -> Int {
            index.map { Swift.min(Int($0), count) } ?? count
        }
        for op in ops {
            switch op {
            case let .insertElement(id, sceneId, index, elementType, text, customElementId):
                guard let id else { throw ScreenplayModelError.missingId }
                let si = try sceneIndex(sceneId)
                let at = position(index, in: scenes[si].elements.count)
                scenes[si].elements.insert(ScreenplayElementSnap(id: id, type: elementType, text: text, customElementId: customElementId), at: at)
            case let .updateElement(id, elementType, text, customElementId):
                let (si, i) = try findEl(id)
                if let elementType { scenes[si].elements[i].type = elementType }
                if let text { scenes[si].elements[i].text = text }
                if let c = customElementId, !c.isEmpty {
                    scenes[si].elements[i].customElementId = c
                } else if let t = elementType, t != .custom {
                    scenes[si].elements[i].customElementId = nil
                }
            case let .deleteElement(id):
                let (si, i) = try findEl(id)
                scenes[si].elements.remove(at: i)
            case let .moveElement(id, sceneId, index):
                let (si, i) = try findEl(id)
                let el = scenes[si].elements.remove(at: i)
                let ti = try sceneIndex(sceneId)
                scenes[ti].elements.insert(el, at: position(index, in: scenes[ti].elements.count))
            case let .insertScene(id, index, heading):
                guard let id else { throw ScreenplayModelError.missingId }
                let l = live()
                let at: Int
                if let index, Int(index) < l.count {
                    at = scenes.firstIndex(where: { $0.id == l[Int(index)].id })!
                } else {
                    at = scenes.count
                }
                scenes.insert(ScreenplaySceneSnap(id: id, heading: heading), at: at)
            case let .moveScene(id, index):
                let s = scenes.remove(at: try sceneIndex(id))
                let l = live()
                let at = Int(index) >= l.count ? scenes.count : scenes.firstIndex(where: { $0.id == l[Int(index)].id })!
                scenes.insert(s, at: at)
            case let .updateScene(id, heading):
                scenes[try sceneIndex(id)].heading = heading
            case let .deleteScene(id):
                deleted.insert(id)
            case .splitScene:
                throw ScreenplayModelError.unsupportedOp("splitScene")
            case .mergeScene:
                throw ScreenplayModelError.unsupportedOp("mergeScene")
            }
        }
        return live()
    }
}
